mapper.select:
SELECT u.USER_NO AS userNo, u.EMP_NO AS empNo, u.USER_ID AS userId, u.USE_YN AS useYn, u.ACCT_LOCK_YN AS acctLockYn, u.LOGIN_FAIL_ATMT_CNT AS loginFailAtmtCnt, DATE_FORMAT(u.LAST_LOGIN_DT, '%Y-%m-%d %H:%i:%s') AS lastLoginDt, DATE_FORMAT(u.REGIST_DT, '%Y-%m-%d %H:%i:%s') AS registDt, DATE_FORMAT(u.UPDT_DT, '%Y-%m-%d %H:%i:%s') AS updtDt, e.EMP_NM AS empNm, d.DEPT_NM AS deptNm FROM com_user u LEFT JOIN hrm_emp_master e ON u.EMP_NO = e.EMP_NO LEFT JOIN hrm_dept_master d ON e.DEPT_CD = d.DEPT_CD
AND u.USER_ID LIKE CONCAT('%', #{userId}, '%')
AND u.EMP_NO LIKE CONCAT('%', #{empNo}, '%')
AND u.USE_YN = #{useYn}
ORDER BY u.REGIST_DT DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE com_user
SET
    USE_YN       = #{useYn},
    ACCT_LOCK_YN = #{acctLockYn}
WHERE USER_ID = #{userId}
